<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getCommunities } from '../../api/community.js'
import { getResidentDetail, getResidentSummary, getResidents } from '../../api/resident.js'
import { apiMessage } from '../../api/http.js'
import PaginationBar from '../../components/common/PaginationBar.vue'

const loading = ref(false), communities = ref([]), rows = ref([]), total = ref(0), summary = ref({}), drawer = ref(false), detail = ref(null)
const query = reactive({ keyword: '', communityId: null, occupancyStatus: '', residenceRole: '', relationToResponsible: '', page: 1, pageSize: 20 })
const occupancyLabels = { OWNER_OCCUPIED: '业主自住', TENANT_OCCUPIED: '租户入住', AVAILABLE_FOR_RENT: '待出租', VACANT: '空置' }
const roleLabels = { RESPONSIBLE: '责任居住人', MEMBER: '共同居住人' }
const relationLabels = { SELF: '本人', SPOUSE: '配偶', PARENT: '父母', CHILD: '子女', SIBLING: '兄弟姐妹', ROOMMATE: '合租人', OTHER: '其他' }
const summaryCards = computed(() => [['当前有效居住人数', summary.value.activeResidentCount], ['RESPONSIBLE 数', summary.value.responsibleCount], ['业主自住', summary.value.ownerOccupiedCount], ['租户入住', summary.value.tenantOccupiedCount], ['待出租', summary.value.availableForRentCount], ['空置', summary.value.vacantCount]])
async function load() { loading.value = true; try { const [page, nextSummary] = await Promise.all([getResidents(query), getResidentSummary()]); rows.value = page.records; total.value = page.total; summary.value = nextSummary } catch (e) { ElMessage.error(apiMessage(e, '居住人员加载失败')) } finally { loading.value = false } }
async function open(row) { try { detail.value = await getResidentDetail(row.residenceId); drawer.value = true } catch (e) { ElMessage.error(apiMessage(e, '人员详情加载失败')) } }
function reset() { Object.assign(query, { keyword: '', communityId: null, occupancyStatus: '', residenceRole: '', relationToResponsible: '', page: 1 }); load() }
function onPageChange(){load()}
onMounted(async () => { try { communities.value = await getCommunities() } catch (e) { ElMessage.error(apiMessage(e)) }; load() })
</script>
<template>
  <section v-loading="loading">
    <div class="kpis"><article v-for="[label, value] in summaryCards" :key="label" class="panel"><span>{{ label }}</span><b>{{ value || 0 }}</b></article></div>
    <section class="panel page"><div class="filters"><el-input v-model="query.keyword" clearable placeholder="姓名、手机号或房号" @keyup.enter="query.page = 1; load()"/><el-select v-model="query.communityId" clearable placeholder="全部小区"><el-option v-for="c in communities" :key="c.communityId" :label="c.communityName" :value="c.communityId"/></el-select><el-select v-model="query.occupancyStatus" clearable placeholder="房屋状态"><el-option v-for="(label, key) in occupancyLabels" :key="key" :label="label" :value="key"/></el-select><el-select v-model="query.residenceRole" clearable placeholder="居住身份"><el-option v-for="(label, key) in roleLabels" :key="key" :label="label" :value="key"/></el-select><el-select v-model="query.relationToResponsible" clearable placeholder="与责任居住人关系"><el-option v-for="(label, key) in relationLabels" :key="key" :label="label" :value="key"/></el-select><el-button type="primary" @click="query.page = 1; load()">查询</el-button><el-button @click="reset">重置</el-button></div><el-table :data="rows" height="calc(100vh - 440px)" @row-click="open"><el-table-column prop="fullName" label="姓名"/><el-table-column prop="maskedPhone" label="手机号"/><el-table-column prop="communityName" label="小区"/><el-table-column prop="buildingName" label="楼栋"/><el-table-column prop="unitName" label="单元"/><el-table-column prop="propertyNo" label="房号"/><el-table-column label="居住身份"><template #default="{ row }"><el-tag>{{ roleLabels[row.residenceRole] || row.residenceRole }}</el-tag></template></el-table-column><el-table-column label="关系"><template #default="{ row }">{{ relationLabels[row.relationToResponsible] || row.relationToResponsible }}</template></el-table-column><el-table-column label="房屋状态"><template #default="{ row }"><el-tag :type="row.occupancyStatus === 'OWNER_OCCUPIED' ? 'success' : row.occupancyStatus === 'TENANT_OCCUPIED' ? 'primary' : row.occupancyStatus === 'AVAILABLE_FOR_RENT' ? 'warning' : 'info'">{{ occupancyLabels[row.occupancyStatus] || row.occupancyStatus }}</el-tag></template></el-table-column><el-table-column prop="startDate" label="入住日期"/><el-table-column label="操作"><template #default="{ row }"><el-button link type="primary" @click.stop="open(row)">详情</el-button></template></el-table-column></el-table><PaginationBar v-model:page="query.page" v-model:page-size="query.pageSize" :total="total" @change="onPageChange"/></section>
    <el-drawer v-model="drawer" size="520px" title="居住详情"><template v-if="detail"><el-descriptions :column="1" border><el-descriptions-item label="人员">{{ detail.fullName }}（{{ detail.maskedPhone || '未填' }}）</el-descriptions-item><el-descriptions-item label="当前住所">{{ detail.fullLocation }}</el-descriptions-item><el-descriptions-item label="责任居住人">{{ detail.responsibleName }}</el-descriptions-item><el-descriptions-item label="当前产权人">{{ detail.ownerName }}</el-descriptions-item><el-descriptions-item label="居住身份">{{ roleLabels[detail.residenceRole] || detail.residenceRole }}</el-descriptions-item><el-descriptions-item label="关系">{{ relationLabels[detail.relationToResponsible] || detail.relationToResponsible }}</el-descriptions-item><el-descriptions-item label="房屋占用状态">{{ occupancyLabels[detail.occupancyStatus] || detail.occupancyStatus }}</el-descriptions-item><el-descriptions-item label="入住日期">{{ detail.startDate }}</el-descriptions-item></el-descriptions></template></el-drawer>
  </section>
</template>
<style scoped>.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:14px;margin-bottom:17px}.kpis article,.page{padding:18px}.kpis span{display:block;color:#718692;font-size:12px}.kpis b{display:block;margin-top:10px;color:#14394a;font-size:22px}.filters{display:grid;grid-template-columns:1.4fr repeat(4,1fr) auto auto;gap:10px;margin-bottom:16px}.pager{display:flex;justify-content:space-between;align-items:center;margin-top:16px;color:#718692;font-size:12px}@media(max-width:1450px){.kpis{grid-template-columns:repeat(3,1fr)}.filters{grid-template-columns:repeat(3,1fr) auto auto}}</style>
